CREATE OR REPLACE FUNCTION public.billing_validate_plan_features() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE k text; v jsonb; BEGIN IF jsonb_typeof(NEW.features)<>'object' THEN RAISE EXCEPTION 'features deve ser objeto'; END IF; FOR k,v IN SELECT * FROM jsonb_each(NEW.features) LOOP IF k='matchmaking_monthly_quota' THEN IF jsonb_typeof(v)<>'number' OR v::text::numeric<0 OR v::text::numeric<>trunc(v::text::numeric) OR v::text::numeric>2147483647 THEN RAISE EXCEPTION 'Franquia deve ser inteiro não negativo'; END IF; ELSIF k IN ('matchmaking_enabled','can_access_community_showcase','can_create_gente_em_acao','can_access_referrals','can_access_business_deals','can_access_testimonials','can_access_opportunities','can_access_referral_requests','can_access_feed','can_access_contents','can_access_council','can_access_meetings','public_profile_enabled','ai_pitch_enabled') THEN IF jsonb_typeof(v)<>'boolean' THEN RAISE EXCEPTION 'Recurso % deve ser booleano',k; END IF; ELSE RAISE EXCEPTION 'Recurso desconhecido: %',k; END IF; END LOOP; IF NEW.audience='assinante' AND (NEW.features @> '{"public_profile_enabled":true}' OR NEW.features @> '{"ai_pitch_enabled":true}' OR NEW.features @> '{"can_access_council":true}' OR NEW.features @> '{"can_access_opportunities":true}' OR NEW.features @> '{"can_access_referral_requests":true}') THEN RAISE EXCEPTION 'Recursos exclusivos de Membros não podem ser liberados a Assinantes'; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.get_user_entitlements(_user_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE r jsonb; BEGIN IF auth.uid() IS NULL OR (auth.uid()<>_user_id AND NOT public.has_role(auth.uid(),'admin')) THEN RAISE EXCEPTION 'Sem permissão'; END IF; SELECT jsonb_build_object('subscription_id',s.id,'status',s.status,'plan_id',p.id,'plan_name',p.name,'audience',p.audience,'features',p.features) INTO r FROM public.billing_subscriptions s JOIN public.billing_plans p ON p.id=s.plan_id JOIN public.profiles pr ON pr.id=s.profile_id WHERE s.profile_id=_user_id AND pr.is_active AND s.status='active' AND s.start_date <= (now() AT TIME ZONE 'America/Sao_Paulo')::date AND p.active AND (NOT public.is_subscriber(_user_id) OR p.audience='assinante') ORDER BY s.start_date DESC,s.created_at DESC,s.id LIMIT 1; RETURN jsonb_build_object('roles',(SELECT coalesce(jsonb_agg(role),'[]'::jsonb) FROM public.user_roles WHERE user_id=_user_id),'subscription',r,'has_subscription_history',EXISTS(SELECT 1 FROM public.billing_subscriptions WHERE profile_id=_user_id)); END $$;
CREATE OR REPLACE FUNCTION public.has_module_access(_user_id uuid,_feature text) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE f jsonb; audience text; internal boolean; subscriber boolean; history boolean; BEGIN IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=_user_id AND is_active) THEN RETURN false; END IF; IF _feature='can_access_community_showcase' AND public.has_role(_user_id,'admin') THEN RETURN true; END IF; internal:=public.has_role(_user_id,'membro') OR public.has_role(_user_id,'facilitador'); subscriber:=public.is_subscriber(_user_id); SELECT p.features,p.audience INTO f,audience FROM public.billing_subscriptions s JOIN public.billing_plans p ON p.id=s.plan_id WHERE s.profile_id=_user_id AND s.status='active' AND s.start_date<=(now() AT TIME ZONE 'America/Sao_Paulo')::date AND p.active AND (NOT subscriber OR p.audience='assinante') ORDER BY s.start_date DESC,s.created_at DESC,s.id LIMIT 1; IF _feature IN ('public_profile_enabled','ai_pitch_enabled') THEN RETURN internal AND audience IN ('premium','membro') AND coalesce((f->>_feature)::boolean,false); END IF; IF _feature IN ('can_access_council','can_access_opportunities','can_access_referral_requests') AND NOT internal AND NOT public.has_role(_user_id,'admin') THEN RETURN false; END IF; IF public.has_role(_user_id,'admin') THEN RETURN true; END IF; IF public.has_role(_user_id,'convidado') AND NOT internal AND NOT subscriber THEN RETURN _feature='can_access_community_showcase'; END IF; IF NOT internal AND NOT subscriber THEN RETURN false; END IF; IF _feature='can_access_community_showcase' AND internal THEN RETURN coalesce((f->>_feature)::boolean,false); END IF; history:=EXISTS(SELECT 1 FROM public.billing_subscriptions WHERE profile_id=_user_id); IF f IS NULL THEN RETURN internal AND NOT history; END IF; IF f ? _feature THEN RETURN (f->>_feature)::boolean; END IF; IF _feature='matchmaking_enabled' THEN RETURN internal OR coalesce((f->>'matchmaking_monthly_quota')::integer,0)>0; END IF; IF internal THEN RETURN true; END IF; RETURN _feature IN ('can_access_community_showcase','can_access_referrals','can_access_business_deals','can_access_testimonials','can_access_feed','can_access_contents'); END $$;
REVOKE ALL ON FUNCTION public.has_module_access(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.has_module_access(uuid,text) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.admin_assign_person_plan(_profile_id uuid,_plan_id uuid,_start_date date DEFAULT CURRENT_DATE,_as_subscriber boolean DEFAULT false,_reactivate boolean DEFAULT false,_team_id uuid DEFAULT NULL,_role app_role DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.billing_plans%ROWTYPE; pr public.profiles%ROWTYPE; existing public.billing_subscriptions%ROWTYPE; sid uuid; lead public.crm_leads%ROWTYPE; target_role public.app_role; BEGIN IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin') OR NOT public.is_active_user(auth.uid()) THEN RAISE EXCEPTION 'Apenas Admin ativo'; END IF; SELECT * INTO pr FROM public.profiles WHERE id=_profile_id FOR UPDATE; IF pr.id IS NULL THEN RAISE EXCEPTION 'Pessoa não encontrada'; END IF; SELECT * INTO p FROM public.billing_plans WHERE id=_plan_id AND active; IF p.id IS NULL THEN RAISE EXCEPTION 'Plano inativo ou inexistente'; END IF; IF _start_date IS NULL THEN RAISE EXCEPTION 'Informe a data inicial'; END IF; target_role:=CASE WHEN _as_subscriber THEN 'assinante'::public.app_role ELSE _role END; IF p.audience='assinante' AND NOT _as_subscriber THEN RAISE EXCEPTION 'Confirme a alteração para Assinante'; END IF; IF _as_subscriber THEN IF p.audience<>'assinante' OR p.plan_type<>'recorrente' OR p.billing_interval<>'monthly' THEN RAISE EXCEPTION 'Assinante exige plano mensal para Assinantes'; END IF; IF EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_profile_id AND role IN ('admin','facilitador','membro')) THEN RAISE EXCEPTION 'Converta o papel interno pelo fluxo de gestão antes de atribuir plano Assinante'; END IF; END IF; IF NOT pr.is_active AND NOT _reactivate THEN RAISE EXCEPTION 'Use reativação com plano'; END IF; IF _reactivate AND target_role NOT IN ('assinante','convidado','membro','facilitador') THEN RAISE EXCEPTION 'Selecione o papel'; END IF; IF target_role IN ('membro','facilitador') AND (_team_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.teams WHERE id=_team_id)) THEN RAISE EXCEPTION 'Selecione um Grupo válido'; END IF; SELECT * INTO existing FROM public.billing_subscriptions WHERE profile_id=_profile_id AND status IN ('active','draft','past_due') ORDER BY created_at DESC LIMIT 1 FOR UPDATE; IF existing.id IS NOT NULL AND (existing.plan_id<>_plan_id OR existing.status<>'active') THEN RAISE EXCEPTION 'Já existe assinatura em aberto; revise ou cancele antes de atribuir'; END IF; IF existing.id IS NULL THEN INSERT INTO public.billing_subscriptions(plan_id,profile_id,status,start_date,next_charge_date,amount_cents,created_by,notes) VALUES(_plan_id,_profile_id,'active',_start_date,_start_date,p.amount_cents,auth.uid(),'Atribuição administrativa; não comprova pagamento') RETURNING id INTO sid; ELSE sid:=existing.id; END IF; IF _reactivate THEN UPDATE public.profiles SET is_active=true,deactivated_at=NULL,deactivation_reason=NULL WHERE id=_profile_id; END IF; IF _as_subscriber OR _reactivate THEN DELETE FROM public.team_members WHERE user_id=_profile_id; DELETE FROM public.user_roles WHERE user_id=_profile_id; INSERT INTO public.user_roles(user_id,role) VALUES(_profile_id,target_role); IF target_role IN ('membro','facilitador') THEN INSERT INTO public.team_members(user_id,team_id,is_facilitator) VALUES(_profile_id,_team_id,target_role='facilitador'); END IF; END IF; IF _reactivate THEN UPDATE public.rescue_dispatches SET status='cancelled',cancel_reason='reativacao_com_plano' WHERE profile_id=_profile_id AND status='queued'; END IF; SELECT * INTO lead FROM public.crm_leads WHERE profile_id=_profile_id AND archived_at IS NULL ORDER BY created_at LIMIT 1; IF lead.id IS NOT NULL THEN INSERT INTO public.crm_lead_history(lead_id,from_status,to_status,moved_by,event_type,reason,metadata) VALUES(lead.id,lead.status,lead.status,auth.uid(),'plan_assigned','Plano atribuído administrativamente',jsonb_build_object('subscription_id',sid,'plan_id',p.id,'role',target_role,'reactivated',_reactivate)); END IF; INSERT INTO public.activity_feed(user_id,activity_type,reference_id,title,description,metadata) VALUES(_profile_id,'plan_assigned',sid,CASE WHEN _reactivate THEN 'Seu acesso foi reativado' ELSE 'Seu plano foi atualizado' END,p.name,jsonb_build_object('admin_id',auth.uid(),'plan_id',p.id,'role',target_role,'reactivated',_reactivate)); RETURN jsonb_build_object('success',true,'subscription_id',sid,'role',target_role); END $$;
REVOKE ALL ON FUNCTION public.admin_assign_person_plan(uuid,uuid,date,boolean,boolean,uuid,app_role) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.admin_assign_person_plan(uuid,uuid,date,boolean,boolean,uuid,app_role) TO authenticated;
CREATE OR REPLACE FUNCTION public.get_community_showcase() RETURNS TABLE(id uuid,full_name text,company text,"position" text,avatar_url text,business_segment text,what_i_do text,ideal_client text,tags text[],role text) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.has_module_access(auth.uid(),'can_access_community_showcase') THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501'; END IF; RETURN QUERY SELECT p.id,p.full_name,p.company,p.position,p.avatar_url,p.business_segment,p.what_i_do,p.ideal_client,coalesce(p.tags,ARRAY[]::text[]),CASE WHEN public.has_role(p.id,'assinante') THEN 'assinante' ELSE 'convidado' END FROM public.profiles p WHERE p.id<>auth.uid() AND public.is_showcase_profile(p.id) ORDER BY p.full_name; END $$;
CREATE OR REPLACE FUNCTION public.get_community_profile(_profile_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE r jsonb; BEGIN IF auth.uid() IS NULL OR NOT public.has_module_access(auth.uid(),'can_access_community_showcase') OR NOT public.is_showcase_profile(_profile_id) THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501'; END IF; SELECT jsonb_build_object('id',p.id,'full_name',p.full_name,'company',p.company,'position',p.position,'avatar_url',p.avatar_url,'bio',p.bio,'what_i_do',p.what_i_do,'ideal_client',p.ideal_client,'how_to_refer_me',p.how_to_refer_me,'business_segment',p.business_segment,'phone',p.phone,'linkedin_url',p.linkedin_url,'instagram_url',p.instagram_url,'website_url',p.website_url,'availability_note',p.availability_note) INTO r FROM public.profiles p WHERE p.id=_profile_id; RETURN r; END $$;
REVOKE ALL ON FUNCTION public.get_community_profile(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.get_community_profile(uuid) TO authenticated;
DO $$ DECLARE item record; BEGIN FOR item IN SELECT * FROM (VALUES ('get_matchmaking_profiles()', 'matchmaking_enabled'),('get_matchmaking_draw_state()','matchmaking_enabled'),('draw_matchmaking_suggestion(uuid)','matchmaking_enabled')) AS x(signature,feature) LOOP EXECUTE replace(pg_get_functiondef(to_regprocedure('public.'||item.signature)),E'BEGIN\n',E'BEGIN\n  IF auth.uid() IS NULL OR NOT public.has_module_access(auth.uid(), '''||item.feature||E''') THEN RAISE EXCEPTION ''Recurso não disponível no plano'' USING ERRCODE=''42501''; END IF;\n'); END LOOP; END $$;
DO $$ DECLARE def text; BEGIN def:=pg_get_functiondef('public._matchmaking_draw_state(uuid)'::regprocedure); def:=replace(def,'AND s.status IN (''active'', ''trialing'')','AND s.status = ''active'' AND s.start_date <= (now() AT TIME ZONE ''America/Sao_Paulo'')::date AND (NOT is_subscriber OR p.audience = ''assinante'')'); def:=replace(def,'IF quota IS NOT NULL THEN','IF NOT public.has_module_access(_user_id, ''matchmaking_enabled'') THEN reason := ''Recurso não disponível no plano''; ELSIF quota IS NOT NULL THEN'); EXECUTE def; def:=pg_get_functiondef('public.create_guest_invitation(text,text,text,uuid,uuid,text,text)'::regprocedure); def:=replace(def,'v_role=''convidado''','v_role IN (''convidado'',''assinante'')'); EXECUTE def; END $$;
DO $$ DECLARE t text; f text; BEGIN FOR t,f IN SELECT * FROM (VALUES ('activity_feed','can_access_feed'),('contents','can_access_contents'),('gente_em_acao','can_create_gente_em_acao'),('meeting_requests','can_create_gente_em_acao'),('referrals','can_access_referrals'),('business_deals','can_access_business_deals'),('testimonials','can_access_testimonials'),('opportunities','can_access_opportunities'),('referral_requests','can_access_referral_requests'),('council_posts','can_access_council'),('council_replies','can_access_council')) AS x(t,f) LOOP EXECUTE format('CREATE POLICY plan_module_access ON public.%I AS RESTRICTIVE FOR ALL TO authenticated USING (public.has_module_access(auth.uid(), %L)) WITH CHECK (public.has_module_access(auth.uid(), %L))',t,f,f); END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.validate_subscriber_interaction() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE actor uuid; target uuid; BEGIN IF TG_TABLE_NAME='meeting_requests' THEN actor:=NEW.requester_id; target:=NEW.recipient_id; ELSIF TG_TABLE_NAME='gente_em_acao' THEN actor:=NEW.user_id; target:=NEW.partner_id; ELSIF TG_TABLE_NAME='referrals' THEN actor:=NEW.from_user_id; target:=NEW.to_user_id; ELSIF TG_TABLE_NAME='testimonials' THEN actor:=NEW.from_user_id; target:=NEW.to_user_id; ELSE actor:=NEW.closed_by_user_id; target:=NEW.referred_by_user_id; END IF; IF public.is_subscriber(actor) AND target IS NOT NULL AND NOT public.is_showcase_profile(target) THEN RAISE EXCEPTION 'Assinante só conecta com Assinantes e Convidados ativos'; END IF; RETURN NEW; END $$;
CREATE TRIGGER subscriber_interaction BEFORE INSERT OR UPDATE ON public.meeting_requests FOR EACH ROW EXECUTE FUNCTION public.validate_subscriber_interaction(); CREATE TRIGGER subscriber_interaction BEFORE INSERT OR UPDATE ON public.gente_em_acao FOR EACH ROW EXECUTE FUNCTION public.validate_subscriber_interaction(); CREATE TRIGGER subscriber_interaction BEFORE INSERT OR UPDATE ON public.referrals FOR EACH ROW EXECUTE FUNCTION public.validate_subscriber_interaction(); CREATE TRIGGER subscriber_interaction BEFORE INSERT OR UPDATE ON public.testimonials FOR EACH ROW EXECUTE FUNCTION public.validate_subscriber_interaction(); CREATE TRIGGER subscriber_interaction BEFORE INSERT OR UPDATE ON public.business_deals FOR EACH ROW EXECUTE FUNCTION public.validate_subscriber_interaction();
CREATE OR REPLACE FUNCTION public.get_my_premium_invitations() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.is_subscriber(auth.uid()) THEN RAISE EXCEPTION 'forbidden'; END IF; RETURN (SELECT coalesce(jsonb_agg(jsonb_build_object('id',g.id,'status',g.status,'title',m.title,'meeting_date',m.meeting_date,'meeting_time',m.meeting_time,'location',m.location,'team_name',t.name) ORDER BY m.meeting_date),'[]'::jsonb) FROM public.guest_participations g JOIN public.meetings m ON m.id=g.meeting_id LEFT JOIN public.teams t ON t.id=m.team_id WHERE g.profile_id=auth.uid() AND g.status IN ('invited','confirmed') AND m.meeting_date >= (now() AT TIME ZONE 'America/Sao_Paulo')::date); END $$;
CREATE OR REPLACE FUNCTION public.respond_premium_invitation(_participation_id uuid,_accept boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.is_subscriber(auth.uid()) OR NOT public.is_active_user(auth.uid()) THEN RAISE EXCEPTION 'forbidden'; END IF; UPDATE public.guest_participations SET status=CASE WHEN _accept THEN 'confirmed' ELSE 'cancelled' END,confirmed_at=CASE WHEN _accept THEN now() ELSE NULL END,cancelled_at=CASE WHEN _accept THEN NULL ELSE now() END,updated_at=now() WHERE id=_participation_id AND profile_id=auth.uid() AND status IN ('invited','confirmed'); IF NOT FOUND THEN RAISE EXCEPTION 'Convite indisponível'; END IF; END $$;
REVOKE ALL ON FUNCTION public.get_my_premium_invitations() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.get_my_premium_invitations() TO authenticated; REVOKE ALL ON FUNCTION public.respond_premium_invitation(uuid,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.respond_premium_invitation(uuid,boolean) TO authenticated;
DO $$ DECLARE def text; BEGIN def:=pg_get_functiondef('public.handle_gente_em_acao_insert()'::regprocedure); def:=replace(def,'PERFORM update_all_monthly_points_for_user(NEW.user_id, get_year_month_from_date(NEW.meeting_date));','IF NOT public.is_subscriber(NEW.user_id) THEN PERFORM update_all_monthly_points_for_user(NEW.user_id, get_year_month_from_date(NEW.meeting_date)); END IF;'); EXECUTE def; END $$;
CREATE POLICY subscriber_no_attendance ON public.attendances AS RESTRICTIVE FOR ALL TO authenticated USING (NOT public.is_subscriber(auth.uid())) WITH CHECK (NOT public.is_subscriber(auth.uid()));
INSERT INTO public.system_changelog(version,title,description,category,changes) VALUES('3.55.0','Planos e acesso da Comunidade','Gestão por papel, atribuição explícita de Assinante, vitrine interativa e catraca por plano.','feature','["Contadores por papel","Reativação com plano","Vitrine administrativa e conexões","Matriz de módulos","Convites Premium sem mudança de papel"]'::jsonb);